body.script:
//
					const cfg   = document.getElementById('cfg').dataset;
					const ASSET = cfg.asset;
					// Server-rendered `?as_of=` from the page's own URL — pre-fills
					// the "As Of" input so a specific historical view is
					// bookmarkable. Interpreted as EUROPE/BERLIN wall-clock time
					// (the picker's own zone), same as a value the user types; it
					// is converted to UTC client-side before any backend call.
					// Empty string means "start at now", same as a bare
					// /tm2/<asset> visit.
					const INITIAL_AS_OF = cfg.asOf || '';
					let INTERVAL = '1h';
					const COINBASE_SYMBOL = { BTC: 'BTC-USD', ETH: 'ETH-USD' }[ASSET] || (ASSET + '-USD');
					document.getElementById('exchange-label').textContent = 'Coinbase · ' + COINBASE_SYMBOL;

					// "As Of" — the single moment this whole page is frozen at.
					// The <input type="datetime-local"> and the URL's own
					// `?as_of=` are both EUROPE/BERLIN wall-clock time (DST-aware),
					// per product decision. AS_OF_ISO is the equivalent naive-UTC
					// "YYYY-MM-DDTHH:MM:SS" (converted by berlinNaiveToUtcIso() in
					// setAsOfInput() — the single Berlin→UTC conversion point).
					// Every fetch appends `&as_of=` + AS_OF_ISO, and the Window
					// vertical line is measured back from it (asOfEpochSeconds()),
					// not from real "now".
					let AS_OF_ISO = null;

					function pad(n) { return String(n).padStart(2, '0'); }

					function toDatetimeLocalUTC(date) {
						return date.getUTCFullYear() + '-' + pad(date.getUTCMonth() + 1) + '-' + pad(date.getUTCDate())
							+ 'T' + pad(date.getUTCHours()) + ':' + pad(date.getUTCMinutes());
					}

					// Europe/Berlin wall-clock "YYYY-MM-DDTHH:00" — DST-aware via
					// Intl ('sv-SE' renders ISO-like "YYYY-MM-DD HH:MM:SS"). Minutes
					// are ALWAYS truncated to :00 (the picker only ever operates at
					// hour granularity, matching the Window dropdown's whole-hour
					// steps and the hour-granular trade filtering downstream).
					function toDatetimeLocalBerlin(date) {
						return date.toLocaleString('sv-SE', { timeZone: 'Europe/Berlin' }).replace(' ', 'T').slice(0, 13) + ':00';
					}

					// Europe/Berlin's UTC offset in seconds at `refDate`, DST-aware
					// (CET/CEST) via the same "diff two toLocaleString renderings
					// of the same instant" idiom `tzOffset` below uses.
					function berlinOffsetSeconds(refDate) {
						const utc = new Date(refDate.toLocaleString('en-US', { timeZone: 'UTC' }));
						const berlin = new Date(refDate.toLocaleString('en-US', { timeZone: 'Europe/Berlin' }));
						return (berlin - utc) / 1000;
					}

					// Berlin wall-clock "YYYY-MM-DDTHH:MM[:SS]" -> equivalent
					// naive-UTC "YYYY-MM-DDTHH:MM:SS" (AS_OF_ISO). DST-aware: the
					// offset is resolved for the TARGET date itself (CET vs CEST),
					// not "now". The ~1h ambiguity right at a DST transition is
					// inherent to any naive-local→instant conversion and immaterial
					// for a historical-inspection tool.
					function berlinNaiveToUtcIso(berlinNaive) {
						const [datePart, timePart] = berlinNaive.slice(0, 16).split('T');
						const [y, m, d] = datePart.split('-').map(Number);
						const [H, M] = timePart.split(':').map(Number);
						const guessUTC = Date.UTC(y, m - 1, d, H, M, 0);
						const offsetSec = berlinOffsetSeconds(new Date(guessUTC));
						return toDatetimeLocalUTC(new Date(guessUTC - offsetSec * 1000)) + ':00';
					}

					// The page's own default "As Of" when no `?as_of=` was given —
					// the current Berlin date and hour, minutes zeroed.
					function defaultAsOfBerlinNaive() {
						return toDatetimeLocalBerlin(new Date());
					}

					function setAsOfInput(value) {
						const berlin = value.slice(0, 16);
						document.getElementById('as-of-input').value = berlin;
						AS_OF_ISO = berlinNaiveToUtcIso(berlin);
					}

					// AS_OF_ISO is a naive-UTC string, so `new Date(AS_OF_ISO)`
					// would parse it as browser-LOCAL time in most engines —
					// appending 'Z' forces UTC. null before setAsOfInput()'s first
					// call.
					function asOfEpochSeconds() {
						if (!AS_OF_ISO) return null;
						return Math.floor(Date.parse(AS_OF_ISO + 'Z') / 1000);
					}

					const klineUrl = (iv, limit) =>
						'/api/klines-coinbase/' + ASSET + '?interval=' + iv + '&limit=' + limit + '&as_of=' + encodeURIComponent(AS_OF_ISO);

					// "Window" control — a free-form number + Hours/Days unit
					// picker (mirrors /ll/<asset>'s own Window control, which
					// replaced its former fixed dropdown for the same
					// flexibility reason), fed as a plain trailing-hours count
					// ending at AS_OF_ISO (not "now") into /api/ll-gamma/<asset>.
					// 3 Days default (72h). This is the only trade-domain control (no
					// "Expiry" dropdown: every active expiry is considered, and
					// each one that has usable trades gets its own
					// dominant-leg line). Clamped client-side to WINDOW_MAX_HOURS, mirroring
					// ll_avg_gamma_json's own server-side LL_MAX_WINDOW_HOURS
					// clamp, so the drawn #window-vline never disagrees with
					// what the server actually windowed on. The server also
					// still accepts "all"/"midnight" ?hours= sentinels (not
					// offered here) reachable by a direct API call.
					const WINDOW_MAX_HOURS = 8760; // 1 year — mirrors LL_MAX_WINDOW_HOURS
					let WINDOW_VALUE = 3;
					let WINDOW_UNIT  = 'd'; // 'h' or 'd'
					let WINDOW_HOURS = 72; // 3 days default
					const llGammaUrl = (hoursOverride) =>
						'/api/ll-gamma/' + ASSET + '?hours=' + (hoursOverride || WINDOW_HOURS) + '&as_of=' + encodeURIComponent(AS_OF_ISO);

					// Total trades across every active expiry considered this
					// fetch (the response's own summed `trade_count`, one per
					// drawn line). null until the first refreshLlGamma() resolves.
					let tradeCount = null;

					const tzOffset = (() => {
						let zone;
						try {
							zone = Intl.DateTimeFormat().resolvedOptions().timeZone;
						} catch (e) {
							return 0;
						}
						const d = new Date();
						const utc = new Date(d.toLocaleString('en-US', { timeZone: 'UTC' }));
						const local = new Date(d.toLocaleString('en-US', { timeZone: zone }));
						return (local - utc) / 1000;
					})();

					const THEME_STORAGE_KEY = 'dankbit_theme';
					let DARK_MODE = localStorage.getItem(THEME_STORAGE_KEY) === 'dark';
					function rulerColor() { return DARK_MODE ? '#aaaaaa' : '#555555'; }

					// "Settings" button/dialog — user-pickable colors for this
					// page's own dominant-leg lines (one per active expiry),
					// persisted per-browser to localStorage under a key
					// completely separate from /ll's own 'dankbit_ll_chart_colors',
					// /4l's 'dankbit_4l_chart_colors', /tm's
					// 'dankbit_tm_chart_colors', and the Delta Chart's
					// 'dankbit_chart_colors'. avg1 = the strongest
					// (|dominant gamma value|) expiry's line (light magenta),
					// avg2 = every other expiry's line (dark magenta).
					const COLOR_STORAGE_KEY = 'dankbit_tm2_chart_colors';
					const DEFAULT_COLORS = { avg1: '#FF66FF', avg2: '#8B008B', window123: '#FFA500' };
					let chartColors = Object.assign({}, DEFAULT_COLORS);
					try {
						const savedColors = JSON.parse(localStorage.getItem(COLOR_STORAGE_KEY) || '{}');
						Object.keys(DEFAULT_COLORS).forEach(key => {
							if (savedColors[key]) chartColors[key] = savedColors[key];
						});
					} catch (e) { /* malformed stored value — fall back to defaults */ }

					document.getElementById('theme-select').value = DARK_MODE ? 'dark' : 'light';
					document.body.classList.toggle('dark', DARK_MODE);

					// Watermark — this page only, via Lightweight Charts v4's own
					// built-in `watermark` chart option (drawn onto the chart's own
					// canvas). Fixed mid-gray at moderate alpha, deliberately NOT
					// theme-reactive — a light/dark-switching black-ish/white-ish
					// color went invisible in practice (white-on-white in Light,
					// black-on-black in Dark). Same approach /tm/<asset> uses, just
					// a "2" in the label so a TM and a TM2 tab are told apart at a
					// glance.
					const WATERMARK_TEXT = 'Dankbit Time Machine 2';
					const WATERMARK_COLOR = 'rgba(120,120,120,0.35)';

					const chart = LightweightCharts.createChart(document.getElementById('chart-container'), {
						width: window.innerWidth, height: window.innerHeight,
						layout: {
							background: { type: 'solid', color: DARK_MODE ? '#000000' : '#ffffff' },
							textColor: DARK_MODE ? '#d1d4dc' : '#333333',
						},
						grid: { vertLines: { visible: false }, horzLines: { visible: false } },
						crosshair: { mode: LightweightCharts.CrosshairMode.Normal, horzLine: { labelBackgroundColor: 'blue' } },
						rightPriceScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
						timeScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc', timeVisible: true, secondsVisible: false },
						watermark: { visible: true, text: WATERMARK_TEXT, fontSize: 36, color: WATERMARK_COLOR, horzAlign: 'center', vertAlign: 'center' },
						localization: {
							timeFormatter: ts => new Date(ts * 1000).toLocaleString('de-DE', {
								timeZone: 'UTC',
								month: 'short', day: 'numeric',
								hour: '2-digit', minute: '2-digit',
							}),
						},
					});

					window.addEventListener('resize', () => {
						chart.resize(window.innerWidth, window.innerHeight);
						updateWindowVLine();
					});
					chart.timeScale().subscribeVisibleLogicalRangeChange(() => updateWindowVLine());
					function repositionBelowToolbar() {
						const bar = document.getElementById('tf-bar');
						if (!bar) return;
						const bottom = Math.ceil(bar.getBoundingClientRect().bottom);
						document.documentElement.style.setProperty('--tf-bar-bottom', bottom + 'px');
					}
					window.addEventListener('resize', repositionBelowToolbar);
					repositionBelowToolbar();

					const series = chart.addCandlestickSeries({
						upColor: '#26a69a', downColor: '#ef5350',
						borderVisible: false, wickUpColor: '#26a69a', wickDownColor: '#ef5350',
					});

					const futureAxisSeries = chart.addLineSeries({
						color: 'rgba(0,0,0,0)', lineWidth: 1,
						lastValueVisible: false, priceLineVisible: false, crosshairMarkerVisible: false,
					});

					// The dominant-leg "lines" are horizontal reference lines at
					// the As-Of/Window reading only (createPriceLine()),
					// redrawn fresh whenever As Of/Timeframe/Window changes —
					// one per active expiry that has usable trades in the
					// window. Held in an array so the count can vary freely
					// (0..LL_MAX_EXPIRIES).
					let llLines = [];
					function clearLlLines() {
						llLines.forEach(l => series.removePriceLine(l));
						llLines = [];
					}

					// The last-fetched, already-sorted (by |dominant_value| desc)
					// expiries array from refreshLlGamma() — cached client-side so
					// the "Strongest"/"Other Expiries" checkboxes below can
					// instantly show/hide any line via renderLlLines() without
					// re-fetching /api/ll-gamma/<asset>.
					let lastExpiries = [];

					// The strongest expiry's own line (rank 0 in the sorted
					// array) is gated by this checkbox — checked by default —
					// independent of every OTHER expiry's line below.
					let SHOW_STRONGEST_LINE = true;
					function onToggleStrongestLine() {
						SHOW_STRONGEST_LINE = document.getElementById('strongest-line-toggle').checked;
						renderLlLines();
					}

					// This checkbox — checked by default — controls every
					// OTHER expiry's line; unchecked hides all of them,
					// checked shows only those whose |dominant gamma value|
					// is above OTHER_LINES_MIN_ABS_GAMMA (1000M for BTC, 100M
					// for ETH — ETH's gamma values run about 10x smaller).
					let SHOW_OTHER_LINES = true;
					const OTHER_LINES_MIN_ABS_GAMMA = ASSET === 'ETH' ? 1e8 : 1e9;
					function onToggleOtherLines() {
						SHOW_OTHER_LINES = document.getElementById('other-lines-toggle').checked;
						renderLlLines();
					}

					// Draws llLines from lastExpiries: rank 0 (strongest) only
					// while SHOW_STRONGEST_LINE is checked; every other rank
					// only while SHOW_OTHER_LINES is checked.
					function renderLlLines() {
						clearLlLines();
						lastExpiries.forEach((e, i) => {
							if (i === 0 && !SHOW_STRONGEST_LINE) return;
							if (i > 0 && (!SHOW_OTHER_LINES
								|| Math.abs(e.dominant_value) <= OTHER_LINES_MIN_ABS_GAMMA)) return;
							if (!e.dominant_price) return;
							const color = i === 0 ? chartColors.avg1 : chartColors.avg2;
							llLines.push(series.createPriceLine({
								price: e.dominant_price, color: color, lineWidth: 2,
								lineStyle: LightweightCharts.LineStyle.Solid,
								axisLabelVisible: true, axisLabelColor: color,
								title: e.dominant_leg + ' | ' + formatAbbreviated(e.dominant_value) + ' | ' + e.instrument,
							}));
						});
					}

					// "1D/2D/3D" checkbox — unchecked by default — draws 3
					// more horizontal lines: the single strongest (rank 0)
					// dominant-leg reading over a fixed trailing 24h/48h/72h
					// window each (as of AS_OF_ISO, not real "now"),
					// independent of the page's own free-form "Window"
					// control above. All 3 share one color
					// (chartColors.window123); each line's label carries its
					// own window as a trailing "| 1D"/"| 2D"/"| 3D" segment.
					let window123Lines = [];
					function clearWindow123Lines() {
						window123Lines.forEach(l => series.removePriceLine(l));
						window123Lines = [];
					}

					let SHOW_WINDOW123 = false;
					// Bumped on every toggle and every fetch, so a slower,
					// superseded response (e.g. one that lands after the
					// checkbox was unchecked) never draws its lines.
					let window123RequestSeq = 0;
					function onToggleWindow123() {
						SHOW_WINDOW123 = document.getElementById('window123-toggle').checked;
						window123RequestSeq++; // drop any fetch still in flight
						if (SHOW_WINDOW123) refreshWindow123Lines();
						else clearWindow123Lines();
					}

					// Fetches /api/ll-gamma/<asset>?hours=24/48/72&as_of=... in
					// parallel and draws the single strongest (rank 0)
					// dominant-leg reading from each response as its own price
					// line. A failed fetch leaves the previously drawn lines in
					// place (cleared only once a fresh response arrives), same
					// convention refreshLlGamma() itself uses. No-op while the
					// checkbox is unchecked.
					async function refreshWindow123Lines() {
						if (!SHOW_WINDOW123) return;
						const seq = ++window123RequestSeq;
						try {
							const results = await Promise.all([1, 2, 3].map(days =>
								fetch(llGammaUrl(days * 24)).then(r => r.json())
							));
							if (seq !== window123RequestSeq || !SHOW_WINDOW123) return;
							clearWindow123Lines();
							results.forEach((data, idx) => {
								const days = idx + 1;
								const top = (data.expiries || []).slice()
									.sort((a, b) => b.abs_value - a.abs_value)[0];
								if (!top || !top.dominant_price) return;
								const color = chartColors.window123;
								const label = top.dominant_leg + ' | ' + formatAbbreviated(top.dominant_value)
									+ ' | ' + top.instrument + ' | ' + days + 'D';
								window123Lines.push(series.createPriceLine({
									price: top.dominant_price, color: color, lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Solid,
									axisLabelVisible: true, axisLabelColor: color,
									title: label,
								}));
							});
						} catch (e) { /* keep previously drawn lines on a failed fetch */ }
					}

					function setStatus(text) { document.getElementById('status').textContent = text; }

					function tradeCountSuffix() {
						return tradeCount !== null ? '  ·  ' + tradeCount + ' trades' : '';
					}

					function hoursLabel(hours) {
						if (hours >= 24 && hours % 24 === 0) return (hours / 24) + 'd';
						return hours + 'h';
					}
					function windowLabel() {
						return hoursLabel(WINDOW_HOURS) + ' trailing window';
					}

					function statusText() {
						const berlin = document.getElementById('as-of-input').value || '?';
						const utc = AS_OF_ISO ? AS_OF_ISO + 'Z' : '?';
						return ASSET + ' · TM2 (' + windowLabel() + ')'
							+ '  ·  As of ' + berlin + ' Berlin (' + utc + ')'
							+ tradeCountSuffix();
					}

					function showSpinner() { document.getElementById('spinner').style.display = 'block'; }
					function hideSpinner() { document.getElementById('spinner').style.display = 'none'; }

					function toCandle(k) {
						return { time: Math.floor(k.t / 1000) + tzOffset, open: parseFloat(k.o), high: parseFloat(k.h), low: parseFloat(k.l), close: parseFloat(k.c) };
					}

					let realCandles = [];

					const TF_WINDOW = { '15m': 5, '1h': 30, '4h': 15, '1d': 365 };
					const INTERVAL_SECONDS = { '15m': 15 * 60, '1h': 3600, '4h': 4 * 3600, '1d': 86400 };
					const FUTURE_MARGIN_DAYS = 5;

					function applyVisibleRange() {
						if (!realCandles.length) return;
						const days = TF_WINDOW[INTERVAL] || 15;
						const futureEdge = realCandles[realCandles.length - 1].time + FUTURE_MARGIN_DAYS * 86400;
						chart.timeScale().setVisibleRange({ from: futureEdge - days * 86400, to: futureEdge });
					}

					function rebuildSeriesData() {
						series.setData(realCandles);

						const intervalSec = INTERVAL_SECONDS[INTERVAL] || 3600;
						const lastClose = realCandles.length ? realCandles[realCandles.length - 1].close : 0;
						const lastTime = realCandles.length
							? realCandles[realCandles.length - 1].time
							: (Math.floor(Date.now() / 1000) + tzOffset);
						const count = Math.round(FUTURE_MARGIN_DAYS * 86400 / intervalSec);
						const futureTicks = [];
						for (let i = 1; i <= count; i++) {
							futureTicks.push({ time: lastTime + i * intervalSec, value: lastClose });
						}
						futureAxisSeries.setData(futureTicks);
						updateWindowVLine();
					}

					function effectiveWindowHours() {
						return WINDOW_HOURS;
					}

					function nearestCandleTimeAtOrBefore(t) {
						if (!realCandles.length) return null;
						let lo = 0, hi = realCandles.length - 1, ans = -1;
						while (lo <= hi) {
							const mid = (lo + hi) >> 1;
							if (realCandles[mid].time <= t) { ans = mid; lo = mid + 1; }
							else hi = mid - 1;
						}
						return ans === -1 ? realCandles[0].time : realCandles[ans].time;
					}

					let VLINE_SHOWN = true;
					function onToggleVLine() {
						VLINE_SHOWN = document.getElementById('vline-toggle').checked;
						updateWindowVLine();
					}

					// Positions the single Window reference line (+ label) at the
					// candle effectiveWindowHours() hours before AS_OF_ISO — the
					// start of the currently selected trailing Window, relative to
					// the inspected moment rather than real "now" (asOfEpochSeconds()
					// instead of Date.now(), the one difference from /ll's own
					// updateWindowVLine()). An As-Of moment is frozen, so this line
					// never needs a timer to keep creeping forward.
					function updateWindowVLine() {
						const vline = document.getElementById('window-vline');
						const label = document.getElementById('window-vline-label');
						if (!vline) return;
						const hrs = effectiveWindowHours();
						const asOfEpoch = asOfEpochSeconds();
						const hideAll = () => {
							vline.style.display = 'none';
							if (label) label.style.display = 'none';
						};
						if (!VLINE_SHOWN || hrs === null || hrs === undefined || asOfEpoch === null) { hideAll(); return; }
						const t = asOfEpoch - hrs * 3600 + tzOffset;
						const snapped = nearestCandleTimeAtOrBefore(t);
						const x = snapped === null ? null : chart.timeScale().timeToCoordinate(snapped);
						if (x === null || x === undefined) { hideAll(); return; }
						const rect = chartContainerEl.getBoundingClientRect();
						const left = Math.round(rect.left + x);
						vline.style.left = left + 'px';
						vline.style.display = 'block';
						if (label) {
							label.textContent = hoursLabel(hrs);
							label.style.left = left + 'px';
							label.style.display = 'block';
						}
					}

					function resetChartView() {
						chart.priceScale('right').applyOptions({ autoScale: true });
						applyVisibleRange();
					}

					const contextMenu = document.getElementById('context-menu');

					function hideContextMenu() {
						contextMenu.style.display = 'none';
					}

					function showContextMenu(x, y) {
						contextMenu.style.display = 'block';
						const maxX = window.innerWidth - contextMenu.offsetWidth - 4;
						const maxY = window.innerHeight - contextMenu.offsetHeight - 4;
						contextMenu.style.left = Math.min(x, maxX) + 'px';
						contextMenu.style.top = Math.min(y, maxY) + 'px';
					}

					function onResetChartViewClick() {
						resetChartView();
						hideContextMenu();
					}

					const chartContainerEl = document.getElementById('chart-container');
					chartContainerEl.addEventListener('contextmenu', e => {
						e.preventDefault();
						showContextMenu(e.clientX, e.clientY);
					});
					document.addEventListener('contextmenu', e => {
						if (!chartContainerEl.contains(e.target)) hideContextMenu();
					});
					document.addEventListener('click', hideContextMenu);
					window.addEventListener('resize', hideContextMenu);
					window.addEventListener('scroll', hideContextMenu, true);

					// `preserveView` (used by reloadForAsOf() below) keeps
					// whatever pan/zoom the user already set instead of
					// snapping back to the default TF_WINDOW range — without
					// this, nudging the "As Of" picker by even 1 hour used to
					// discard a manually-adjusted view every time, since this
					// function used to call applyVisibleRange() unconditionally
					// on every reload. The saved range is real epoch
					// timestamps (not bar indices), so it stays valid even
					// though the newly-fetched 500 candles shift by however
					// many bars the As-Of change moved.
					async function loadCandles(preserveView) {
						const savedRange = preserveView ? chart.timeScale().getVisibleRange() : null;
						const resp = await (await fetch(klineUrl(INTERVAL, 500))).json();
						const klines = (resp.result || []).slice().reverse();
						realCandles = klines.map(toCandle);
						rebuildSeriesData();
						if (savedRange) {
							chart.timeScale().setVisibleRange(savedRange);
						} else {
							applyVisibleRange();
						}
						updateWindowVLine();
					}

					async function setTf(iv) {
						INTERVAL = iv;
						await loadCandles();
						setStatus(statusText());
					}

					// Fired on both the number input's and the unit select's
					// onchange (blur/Enter or a unit switch) — same clamp/
					// re-fetch pattern as /ll/<asset>'s own onWindowInputChange().
					// Clamps into 1..WINDOW_MAX_HOURS, writes the clamped value
					// back into the input, then re-fetches the dominant-leg lines
					// against the (unchanged) AS_OF_ISO.
					async function onWindowInputChange() {
						const valInput  = document.getElementById('window-value-input');
						const unitSelect = document.getElementById('window-unit-select');
						WINDOW_UNIT = unitSelect.value === 'd' ? 'd' : 'h';
						let value = parseInt(valInput.value, 10);
						if (!Number.isFinite(value) || value < 1) value = 1;
						let hours = WINDOW_UNIT === 'd' ? value * 24 : value;
						if (hours > WINDOW_MAX_HOURS) {
							hours = WINDOW_MAX_HOURS;
							value = WINDOW_UNIT === 'd' ? Math.floor(hours / 24) : hours;
						}
						WINDOW_VALUE = value;
						WINDOW_HOURS = WINDOW_UNIT === 'd' ? WINDOW_VALUE * 24 : WINDOW_VALUE;
						valInput.value = String(WINDOW_VALUE);
						updateWindowVLine();
						await refreshLlGamma();
						setStatus(statusText());
					}

					function formatAbbreviated(value) {
						const sign = value < 0 ? '-' : '';
						const abs = Math.abs(value);
						if (abs >= 1e6) return sign + Math.round(abs / 1e6).toLocaleString('en-US') + 'M';
						if (abs >= 1e3) return sign + Math.round(abs / 1e3).toLocaleString('en-US') + 'K';
						return sign + Math.round(abs).toLocaleString('en-US');
					}

					// Fetches /api/ll-gamma/<asset> (one dominant-leg gamma
					// reading per active expiry as of AS_OF_ISO, response
					// sorted by |dominant gamma value| desc), caches it into
					// lastExpiries, then calls renderLlLines() to draw the
					// strongest expiry's line only while the "Strongest"
					// checkbox is checked, plus every other expiry's line
					// only while the "Other Expiries" checkbox is checked —
					// mirrors /ll/<asset>'s own behavior. The
					// strongest expiry (rank 0) uses chartColors.avg1 (light
					// magenta), every other expiry uses chartColors.avg2 (dark
					// magenta). Label: "<dom leg> | <dominant gamma value> |
					// <instrument>", e.g. "LC | 71M | BTC-9SEP26". A failed
					// fetch leaves the previously drawn lines in place
					// (cleared only once a fresh response arrives).
					async function refreshLlGamma() {
						showSpinner();
						try {
							const data = await (await fetch(llGammaUrl())).json();
							lastExpiries = (data.expiries || []).slice()
								.sort((a, b) => b.abs_value - a.abs_value);

							tradeCount = typeof data.trade_count === 'number' ? data.trade_count : 0;
							setStatus(statusText());

							renderLlLines();
							refreshWindow123Lines(); // fire-and-forget, own try/catch
						} finally {
							hideSpinner();
						}
					}

					function applyTheme() {
						document.body.classList.toggle('dark', DARK_MODE);
						chart.applyOptions({
							layout: {
								background: { type: 'solid', color: DARK_MODE ? '#000000' : '#ffffff' },
								textColor: DARK_MODE ? '#d1d4dc' : '#333333',
							},
							rightPriceScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
							timeScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
						});
					}

					function onThemeChange() {
						DARK_MODE = document.getElementById('theme-select').value === 'dark';
						localStorage.setItem(THEME_STORAGE_KEY, DARK_MODE ? 'dark' : 'light');
						applyTheme();
					}

					function openSettingsModal() {
						Object.keys(DEFAULT_COLORS).forEach(key => {
							const input = document.getElementById('color-' + key);
							if (input) input.value = chartColors[key];
						});
						document.getElementById('settings-modal').style.display = 'flex';
					}

					function closeSettingsModal() {
						document.getElementById('settings-modal').style.display = 'none';
					}

					function saveChartColors() {
						Object.keys(DEFAULT_COLORS).forEach(key => {
							const input = document.getElementById('color-' + key);
							if (input) chartColors[key] = input.value;
						});
						localStorage.setItem(COLOR_STORAGE_KEY, JSON.stringify(chartColors));
						refreshLlGamma();
						closeSettingsModal();
					}

					function resetChartColors() {
						chartColors = Object.assign({}, DEFAULT_COLORS);
						localStorage.removeItem(COLOR_STORAGE_KEY);
						Object.keys(DEFAULT_COLORS).forEach(key => {
							const input = document.getElementById('color-' + key);
							if (input) input.value = chartColors[key];
						});
						refreshLlGamma();
					}

					let rulerActive = false;
					let rulerPrice1 = null;
					let rulerLines  = [];

					function toggleRuler() {
						rulerActive = !rulerActive;
						document.getElementById('ruler-btn').classList.toggle('active', rulerActive);
						rulerLines.forEach(l => series.removePriceLine(l));
						rulerLines = [];
						rulerPrice1 = null;
						const info = document.getElementById('ruler-info');
						info.style.display = 'none';
						info.textContent = '';
					}

					chart.subscribeClick(param => {
						if (!rulerActive || !param.point) return;
						const price = series.coordinateToPrice(param.point.y);
						if (rulerPrice1 === null) {
							rulerPrice1 = price;
							rulerLines.push(series.createPriceLine({
								price, color: rulerColor(), lineWidth: 1,
								lineStyle: LightweightCharts.LineStyle.Dashed,
								axisLabelVisible: true, axisLabelColor: DARK_MODE ? '#e8e8e8' : '#000000', title: '①',
							}));
						} else {
							rulerLines.push(series.createPriceLine({
								price, color: rulerColor(), lineWidth: 1,
								lineStyle: LightweightCharts.LineStyle.Dashed,
								axisLabelVisible: true, axisLabelColor: DARK_MODE ? '#e8e8e8' : '#000000', title: '②',
							}));
							const pct = ((price - rulerPrice1) / rulerPrice1 * 100);
							const sign = pct >= 0 ? '+' : '';
							const info = document.getElementById('ruler-info');
							info.style.display = 'block';
							info.textContent = rulerPrice1.toFixed(0) + ' → ' + price.toFixed(0) + '   ' + sign + pct.toFixed(2) + '%';
							rulerPrice1 = null;
						}
					});

					// Re-runs every As-Of-dependent fetch against the current
					// AS_OF_ISO — called whenever the "As Of" input changes or the
					// "Now" button is pressed. Candles and the dominant-leg lines
					// both depend on AS_OF_ISO, so both are re-fetched together (unlike
					// setTf/setWindow, which each only touch the one thing they
					// control). loadCandles(true) preserves the user's own
					// pan/zoom instead of resetting it — see loadCandles() above.
					async function reloadForAsOf() {
						showSpinner();
						try {
							await loadCandles(true);
							await refreshLlGamma();
							setStatus(statusText());
						} catch (e) {
							setStatus('Error: ' + e.message);
						} finally {
							hideSpinner();
						}
					}

					function onAsOfChange() {
						const value = document.getElementById('as-of-input').value;
						if (!value) return;
						setAsOfInput(value);
						reloadForAsOf();
					}

					// Jumps the picker to the current Berlin date and hour
					// (minutes zeroed).
					function jumpToNow() {
						setAsOfInput(toDatetimeLocalBerlin(new Date()));
						reloadForAsOf();
					}

					async function init() {
						try {
							setAsOfInput(INITIAL_AS_OF || defaultAsOfBerlinNaive());
							await loadCandles();
							await refreshLlGamma();
							setStatus(statusText());
						}
						catch (e) { setStatus('Error: ' + e.message); }
					}
					init();
					// No setInterval calls at all on this page — an As-Of moment is
					// frozen by definition, so unlike /ll/<asset> (candle poll,
					// dominant-leg-line poll, refresh countdown, vline-advance tick) there's
					// nothing here that needs to keep moving in real time once
					// AS_OF_ISO stops changing.
				//
